create function pg_temp.as_user(u uuid) returns void language plpgsql as $$ begin execute 'reset role'; perform set_config('request.jwt.claim.sub', u::text, false); execute 'set role authenticated'; end $$;
create function pg_temp.ex(n text) returns uuid language sql as $$ select id from public.exercises where name = n limit 1 $$;
create function pg_temp.it(n text, s int, r text, rest int) returns jsonb language sql as $$ select jsonb_build_object('exercise_id', pg_temp.ex(n), 'sets', s, 'reps', r, 'rest_seconds', rest) $$;
create function pg_temp.rnd(k text) returns numeric language sql immutable as $$ select (('x' || substr(md5(k), 1, 8))::bit(32)::bigint % 1000000) / 1000000.0 $$;
create function pg_temp.vid(cid uuid) returns text language plpgsql as $$ declare v text := gen_random_uuid()::text; begin insert into public.video_uploads (video_id, workspace_id, client_id) select v, workspace_id, cid from public.clients where id = cid; return v; end $$;
create function pg_temp.r25(v numeric, tw numeric) returns numeric language sql as $$ select case when tw <= 16 then round(v) else round(v / 2.5) * 2.5 end $$;

-- Historial de entrenos: días del plan entre start y ayer, con constancia "adh", pesos que suben hasta el peso actual del plan.
create function pg_temp.history(cid uuid, start date, adh numeric, seen_until date, upto date default null, sure_from date default null) returns void language plpgsql as $$
declare d date; today date := (now() at time zone 'America/Bogota')::date; pd record; pi record; lid uuid; prog numeric; s int; lo int; w numeric;
begin
  for d in select generate_series(start, coalesce(upto, today - 1), '1 day')::date loop
    select * into pd from public.plan_days where client_id = cid and weekday = extract(isodow from d)::int and plan_id = (select id from public.training_plans where client_id = cid and status = 'active');
    if pd.id is null then continue; end if;
    if d < today and d < coalesce(sure_from, today) and pg_temp.rnd(cid::text || d::text) > adh then continue; end if;
    prog := least(1, greatest(0, (d - start)::numeric / greatest(1, today - start)));
    insert into public.workout_logs (workspace_id, client_id, log_date, plan_day_id, effort, completed_at, created_at, coach_seen_at)
      values (pd.workspace_id, cid, d, pd.id, 6 + floor(pg_temp.rnd('e' || cid || d) * 4)::int, (d + time '18:40') at time zone 'America/Bogota', (d + time '18:00') at time zone 'America/Bogota',
              case when d <= seen_until then (d + time '21:00') at time zone 'America/Bogota' end)
      returning id into lid;
    for pi in select p.*, x.name xname from public.plan_items p join public.exercises x on x.id = p.exercise_id where p.plan_day_id = pd.id order by position loop
      lo := split_part(pi.reps, '-', 1)::int;
      for s in 1..pi.sets loop
        w := case when coalesce(pi.target_weight, 0) = 0 then 0 else pg_temp.r25(pi.target_weight * (0.62 + 0.38 * prog), pi.target_weight) end;
        insert into public.set_logs (workspace_id, client_id, workout_log_id, plan_item_id, exercise_name, set_number, kind, reps, weight, created_at)
          values (pd.workspace_id, cid, lid, pi.id, pi.xname, s, 'work', lo + floor(pg_temp.rnd('r' || pi.id || d || s) * (case when pi.reps like '%-%' then 2.6 else 1.15 end))::int - (case when s = pi.sets then 1 else 0 end), w,
                  (d + time '18:05') at time zone 'America/Bogota' + (pi.position * 8 + s * 2) * interval '1 minute');
      end loop;
    end loop;
  end loop;
end $$;

-- Hábitos diarios: nivel "lvl" (0..1) de constancia.
create function pg_temp.habits(cid uuid, start date, lvl numeric, upto date) returns void language plpgsql as $$
declare d date; r numeric; ws uuid; lect uuid;
begin
  select workspace_id into ws from public.clients where id = cid;
  select id into lect from public.habit_defs where name = 'Lectura' limit 1;
  for d in select generate_series(start, upto, '1 day')::date loop
    r := pg_temp.rnd('h' || cid || d);
    if r > lvl + 0.15 then continue; end if;
    insert into public.habit_logs (client_id, workspace_id, day, water, steps, sleep, extra, updated_at)
      values (cid, ws, d, least(12, 4 + floor(pg_temp.rnd('w' || cid || d) * 3.5 + lvl * 4)::int),
              (2800 + floor(pg_temp.rnd('s' || cid || d) * 4000 + lvl * 5500))::int,
              round((5 + pg_temp.rnd('z' || cid || d) * 1.3 + lvl * 2.1) * 2) / 2,
              case when lect is not null and pg_temp.rnd('l' || cid || d) < lvl * 0.8 then jsonb_build_object(lect::text, 1) else '{}'::jsonb end,
              (d + time '21:30') at time zone 'America/Bogota')
      on conflict (client_id, day) do nothing;
  end loop;
end $$;

