declare jeff uuid := '00000000-0000-0000-0000-0000000000f0'; ws uuid; today date := (now() at time zone 'America/Bogota')::date;
  va uuid; ma uuid; so uuid; c uuid; rec record; pl uuid; tp uuid; t_pg uuid; t_to uuid; t_gf uuid; t_fb uuid; t_up uuid; t_lo uuid; vstart date; d date; i int; nutr uuid;
  completo uuid; esencial uuid; lect uuid; s uuid; m uuid;
begin
  select id into ws from public.workspaces where slug = 'yeffitnes';
  select id into completo from public.plans where name = 'Completo'; select id into esencial from public.plans where name = 'Esencial';
  select id into va from public.clients where profile_id = '00000000-0000-0000-0000-00000000000a';
  select id into ma from public.clients where profile_id = '00000000-0000-0000-0000-00000000000b';
  select id into so from public.clients where profile_id = '00000000-0000-0000-0000-00000000000c';
  perform pg_temp.as_user(jeff);
  -- Hábitos del equipo
  perform public.save_habit_def((select id from public.habit_defs where key = 'water'), 'Agua', 'vasos', 'number', 8, true);
  perform public.save_habit_def((select id from public.habit_defs where key = 'steps'), 'Pasos', 'pasos', 'number', 8000, true);
  perform public.save_habit_def((select id from public.habit_defs where key = 'sleep'), 'Sueño', 'h', 'number', 7, true);
  lect := public.save_habit_def(null, 'Lectura', null, 'check', 4, true);
  -- Rutinas de Jeff
  t_pg := public.save_routine(null, 'Pierna y glúteo', 'Fuerza', 60, jsonb_build_array(pg_temp.it('Sentadilla con barra',4,'8-10',120), pg_temp.it('Hip thrust',4,'10-12',90), pg_temp.it('Prensa de piernas',3,'12',90), pg_temp.it('Curl femoral acostado',3,'12',60), pg_temp.it('Elevación de talones de pie',3,'15',45)), null);
  t_to := public.save_routine(null, 'Torso', 'Fuerza', 50, jsonb_build_array(pg_temp.it('Press de banca con mancuernas',4,'8-10',90), pg_temp.it('Jalón al pecho',4,'10-12',90), pg_temp.it('Remo en polea baja',3,'12',60), pg_temp.it('Press de hombro con mancuernas',3,'10-12',60), pg_temp.it('Face pull',3,'15',45)), null);
  t_gf := public.save_routine(null, 'Glúteo y femoral', 'Hipertrofia', 55, jsonb_build_array(pg_temp.it('Peso muerto rumano',4,'8-10',120), pg_temp.it('Sentadilla búlgara',3,'10',90), pg_temp.it('Abducción de cadera',3,'15',45), pg_temp.it('Patada de glúteo en polea',3,'12',45), pg_temp.it('Crunch en polea',3,'15',45)), null);
  t_fb := public.save_routine(null, 'Cuerpo completo', 'Circuito', 45, jsonb_build_array(pg_temp.it('Sentadilla goblet',3,'12',75), pg_temp.it('Remo con mancuerna a una mano',3,'10-12',60), pg_temp.it('Zancadas con mancuernas',3,'10',60), pg_temp.it('Elevaciones laterales',3,'12-15',45), pg_temp.it('Curl martillo',3,'12',45)), null);
  t_up := public.save_routine(null, 'Empuje', 'Fuerza', 50, jsonb_build_array(pg_temp.it('Press de banca con barra',4,'6-8',150), pg_temp.it('Press inclinado con mancuernas',3,'8-10',90), pg_temp.it('Press militar con barra',3,'8-10',90), pg_temp.it('Elevaciones laterales',3,'12-15',45), pg_temp.it('Extensión de tríceps en polea',3,'12',45)), null);
  t_lo := public.save_routine(null, 'Tirón', 'Fuerza', 50, jsonb_build_array(pg_temp.it('Dominadas asistidas en máquina',4,'8-10',90), pg_temp.it('Remo con barra',4,'8-10',90), pg_temp.it('Remo unilateral en polea',3,'12',60), pg_temp.it('Face pull',3,'15',45), pg_temp.it('Curl con barra',3,'10-12',45)), null);

  -- ===== Valentina: 12 semanas con Jeff =====
  vstart := today - 86;
  tp := public.create_training_plan(va, 'Recomposición · Fase 2');
  perform public.assign_day(tp, 1, t_pg); perform public.assign_day(tp, 3, t_to); perform public.assign_day(tp, 5, t_gf); perform public.assign_day(tp, 7, t_fb);
  reset role;
  update public.training_plans set level = 'intermediate', level_reason = 'Domina la técnica básica y sube carga cada semana.', review_on = today + 10,
    coach_note = 'Fase 2: más carga en pierna y glúteo. Prioriza la técnica en el rumano.', starts_on = today - 30 where id = tp;
  update public.plan_items p set target_weight = v.w from (values
    ('Sentadilla con barra',47.5),('Hip thrust',75),('Prensa de piernas',130),('Curl femoral acostado',32.5),('Elevación de talones de pie',30),
    ('Press de banca con mancuernas',14),('Jalón al pecho',42.5),('Remo en polea baja',37.5),('Press de hombro con mancuernas',10),('Face pull',17.5),
    ('Peso muerto rumano',50),('Sentadilla búlgara',12),('Abducción de cadera',45),('Patada de glúteo en polea',12.5),('Crunch en polea',25),
    ('Sentadilla goblet',20),('Remo con mancuerna a una mano',16),('Zancadas con mancuernas',12),('Elevaciones laterales',7),('Curl martillo',10)) v(n, w)
    where p.client_id = va and p.exercise_id = pg_temp.ex(v.n);
  update public.clients set status = 'active', plan_id = completo, activated_at = (vstart + time '09:00') at time zone 'America/Bogota', plan_since = today - 12,
    onboarded_at = (vstart + time '10:00') at time zone 'America/Bogota', height_cm = 164, start_weight_kg = 68.4, start_point_at = (vstart + time '10:00') at time zone 'America/Bogota',
    objective = 'Bajar grasa y ganar fuerza en pierna y glúteo antes de mi matrimonio en marzo. Quiero sentirme fuerte y con energía todo el día.',
    objective_at = (vstart + time '10:00') at time zone 'America/Bogota', image_consent_at = now() where id = va;
  perform pg_temp.history(va, vstart, 0.9, today - 2, null, today - 40);
  perform pg_temp.habits(va, vstart, 0.82, today - 1);
  -- hoy: agua y pasos de la mañana
  insert into public.habit_logs (client_id, workspace_id, day, water, steps) values (va, ws, today, 3, 4120) on conflict (client_id, day) do update set water = 3, steps = 4120, sleep = 7.5;
  -- medidas semanales
  for i in 0..12 loop
    insert into public.measurements (workspace_id, client_id, measured_on, weight_kg, waist_cm, hip_cm, chest_cm, arm_cm, thigh_cm, recorded_by)
      values (ws, va, vstart + i * 7, round((68.4 - i * 0.44 + (pg_temp.rnd('m' || i) - 0.5) * 0.5)::numeric, 1), round((82 - i * 0.58)::numeric, 1), round((101 - i * 0.3)::numeric, 1),
              round((90 - i * 0.15)::numeric, 1), round((28.5 + i * 0.06)::numeric, 1), round((58 - i * 0.12)::numeric, 1), case when i % 4 = 0 then 'coach' else 'client' end);
  end loop;
  -- nutrición
  perform pg_temp.as_user(jeff);
  update public.nutrition_plans set active = false where client_id = va;
  nutr := public.save_nutrition(null, va, 'Déficit suave · 1.750 kcal', 1750, 125, 180, 58, 'Toma 2,5 L de agua al día. Si un día entrenas más tarde, mueve la merienda para antes del entreno.', jsonb_build_array(
    jsonb_build_object('name','Desayuno','content','3 huevos revueltos con espinaca, 1 arepa mediana y 1 taza de fruta picada.','weekday',null),
    jsonb_build_object('name','Media mañana','content','Yogur griego natural con 30 g de granola sin azúcar.','weekday',null),
    jsonb_build_object('name','Almuerzo','content','150 g de pechuga a la plancha, 1 taza de arroz, ensalada grande con aguacate.','weekday',null),
    jsonb_build_object('name','Pre entreno','content','1 banano y 1 scoop de proteína con agua.','weekday',null),
    jsonb_build_object('name','Cena','content','150 g de pescado blanco, papa cocida mediana y verduras salteadas.','weekday',null)));
  reset role;
  insert into public.meal_logs (client_id, workspace_id, log_date, meal_id, done_at)
    select va, ws, gd::date, nm.id, (gd::date + time '20:00') at time zone 'America/Bogota' from generate_series(today - 13, today - 1, '1 day') gd, public.nutrition_meals nm
    join public.nutrition_plans np on np.id = nm.plan_id where np.client_id = va and np.active and pg_temp.rnd('n' || nm.id || gd) < 0.85;
  insert into public.meal_logs (client_id, workspace_id, log_date, meal_id, done_at)
    select va, ws, today, nm.id, now() from public.nutrition_meals nm join public.nutrition_plans np on np.id = nm.plan_id where np.client_id = va and np.active and nm.position < 2;
  -- reportes diarios (los viejos ya se borraron solos; los recientes tienen vídeo)
  for d in select generate_series(today - 20, today - 1, '1 day')::date loop
    if extract(isodow from d) not in (1,3,5,7) then continue; end if;
    insert into public.daily_reports (workspace_id, client_id, report_date, comment, video_id, video_state, coach_seen_at, delete_after, created_at)
      values (ws, va, d, case (extract(day from d)::int % 4) when 0 then 'Hoy subí a ' || (40 + (d - today + 20) / 2) || ' kg en sentadilla y la sentí estable. La última serie me costó.'
        when 1 then 'Me dolió un poco la rodilla en la búlgara, bajé el peso como me dijiste.' when 2 then 'Entreno completo. Dormí poco pero igual lo saqué.' else 'Probé la técnica nueva del rumano, ¿me la revisas?' end,
        case when d >= today - 2 then pg_temp.vid(va) end, case when d >= today - 2 then 'uploaded' else 'deleted' end,
        case when d < today - 1 then (d + time '21:00') at time zone 'America/Bogota' end, case when d >= today - 2 then now() + interval '30 hours' end, (d + time '19:30') at time zone 'America/Bogota');
  end loop;
  -- comentarios de Jeff en entrenos
  update public.workout_logs set coach_comment = 'Muy bien esa sentadilla. La próxima semana sube 2,5 kg y mantén las 8 repeticiones.', feedback_seen_at = now()
    where id = (select id from public.workout_logs where client_id = va and log_date < today - 2 order by log_date desc limit 1);
  update public.workout_logs set coach_comment = 'Constancia perfecta esta semana. Así se construye.', feedback_seen_at = now()
    where id = (select id from public.workout_logs where client_id = va order by log_date desc offset 6 limit 1);
  -- mensajes
