    (ws, va, 'client', 'Yeff, ¿puedo cambiar el día de pierna al martes esta semana? Tengo un viaje el lunes.', now() - interval '3 days 4 hours', now() - interval '3 days'),
    (ws, va, 'coach', 'Claro. Haz pierna el martes y torso el miércoles como siempre. Solo deja 48 h entre pierna y glúteo.', now() - interval '3 days 2 hours', now() - interval '3 days'),
    (ws, va, 'client', '¡Gracias! Ya me midió la cintura la nutri: 75 cm. Empecé en 82', now() - interval '1 day 3 hours', now() - interval '1 day'),
    (ws, va, 'coach', 'Eso es trabajo tuyo. 7 cm en 12 semanas sin perder fuerza. Seguimos.', now() - interval '1 day 2 hours', now() - interval '20 hours');
  insert into public.client_notes (workspace_id, client_id, body, created_at) values
    (ws, va, 'Molestia antigua en rodilla izquierda: nada de saltos. Búlgara con poco peso y controlada.', now() - interval '80 days'),
    (ws, va, 'Se casa en marzo. Meta: cintura 72 cm y hip thrust con 90 kg.', now() - interval '40 days');

  -- ===== Otros clientes =====
  for rec in select * from (values
      ('00000000-0000-0000-0000-00000000000b'::uuid, 'Esencial', 35, 0.75, 0.55, 'Ganar masa muscular en tren superior.', 1),
      ('00000000-0000-0000-0000-0000000000d1'::uuid, 'Completo', 63, 0.92, 0.9, 'Correr mi primera media maratón sin lesionarme.', 2),
      ('00000000-0000-0000-0000-0000000000d2'::uuid, 'Esencial', 49, 0.45, 0.3, 'Bajar 8 kg y mejorar la espalda.', 1),
      ('00000000-0000-0000-0000-0000000000d3'::uuid, 'Completo', 23, 0.85, 0.7, 'Tonificar y tener más energía después del embarazo.', 2),
      ('00000000-0000-0000-0000-0000000000d4'::uuid, 'Completo', 112, 0.8, 0.6, 'Ganar fuerza: press de banca de 100 kg.', 1),
      ('00000000-0000-0000-0000-0000000000d5'::uuid, 'Esencial', 14, 0.7, 0.75, 'Crear el hábito de entrenar 3 veces por semana.', 2),
      ('00000000-0000-0000-0000-0000000000d6'::uuid, 'Esencial', 70, 0.35, 0.2, 'Perder la barriga y dormir mejor.', 1),
      ('00000000-0000-0000-0000-0000000000d7'::uuid, 'Completo', 28, 0.88, 0.8, 'Glúteo más fuerte y menos dolor lumbar.', 2)) v(pid, plan, days, adh, hab, obj, kind) loop
    select id into c from public.clients where profile_id = rec.pid;
    update public.clients set status = 'active', plan_id = (select id from public.plans where name = rec.plan), activated_at = now() - (rec.days || ' days')::interval,
      plan_since = today - (rec.days % 30), onboarded_at = now() - (rec.days || ' days')::interval, start_point_at = now() - (rec.days || ' days')::interval,
      height_cm = case when rec.kind = 1 then 176 else 162 end, start_weight_kg = case when rec.kind = 1 then 82 else 63 end,
      objective = rec.obj, objective_at = now() - (rec.days || ' days')::interval where id = c;
    perform pg_temp.as_user(jeff);
    tp := public.create_training_plan(c, 'Plan ' || split_part((select full_name from public.profiles where id = rec.pid), ' ', 1));
    if rec.kind = 1 then perform public.assign_day(tp, 1, t_up); perform public.assign_day(tp, 3, t_pg); perform public.assign_day(tp, 5, t_lo);
    else perform public.assign_day(tp, 2, t_pg); perform public.assign_day(tp, 4, t_to); perform public.assign_day(tp, 7, t_gf); end if;
    reset role;
    update public.plan_items set target_weight = case when rec.kind = 1 then 40 else 25 end where client_id = c;
    perform pg_temp.history(c, today - rec.days, rec.adh, today - 2, case when rec.kind = 2 and rec.adh > 0.8 then today else today - 1 end);
    perform pg_temp.habits(c, today - rec.days, rec.hab, today - 1);
    insert into public.measurements (workspace_id, client_id, measured_on, weight_kg, waist_cm, recorded_by)
      select ws, c, today - rec.days + g * 7, case when rec.kind = 1 then 82 else 63 end - g * 0.3, case when rec.kind = 1 then 92 else 78 end - g * 0.4, 'client'
      from generate_series(0, rec.days / 7) g;
  end loop;
  -- Juan Pablo y Felipe: más de 5 días sin entrenar (para "en riesgo")
  delete from public.set_logs where workout_log_id in (select w.id from public.workout_logs w join public.clients c2 on c2.id = w.client_id where c2.profile_id in ('00000000-0000-0000-0000-0000000000d2','00000000-0000-0000-0000-0000000000d6') and w.log_date > today - 7);
  delete from public.workout_logs w using public.clients c2 where c2.id = w.client_id and c2.profile_id in ('00000000-0000-0000-0000-0000000000d2','00000000-0000-0000-0000-0000000000d6') and w.log_date > today - 7;
  -- planes que vencen: Natalia en 2 días, Santiago hoy
  update public.clients set plan_since = today - 28 where profile_id = '00000000-0000-0000-0000-0000000000d3';
  update public.clients set plan_since = today - 30 where profile_id = '00000000-0000-0000-0000-0000000000d4';
  -- reportes sin revisar de otros clientes
  insert into public.daily_reports (workspace_id, client_id, report_date, comment, video_id, video_state, delete_after, created_at)
    select ws, c2.id, today - 1, x.cm, pg_temp.vid(c2.id), 'uploaded', now() + interval '30 hours', now() - interval '14 hours'
    from (values ('00000000-0000-0000-0000-0000000000d1'::uuid, 'Hice el rumano con 45 kg. ¿Bajo la cadera más?'), ('00000000-0000-0000-0000-0000000000d7'::uuid, 'Primera vez que hago hip thrust sin dolor lumbar.'),
                 ('00000000-0000-0000-0000-00000000000b'::uuid, 'Revisa mi press de banca, siento el hombro.')) x(pid, cm) join public.clients c2 on c2.profile_id = x.pid;
  -- entrenos de ayer sin revisar
  update public.workout_logs set coach_seen_at = null where log_date >= today - 1;
  -- mensajes sin leer
  insert into public.messages (workspace_id, client_id, sender, body, created_at)
    select ws, c2.id, 'client', x.b, now() - x.ago from (values
      ('00000000-0000-0000-0000-0000000000d3'::uuid, '¿El plan se renueva solo o te transfiero? Me vence en 2 días.', interval '5 hours'),
      ('00000000-0000-0000-0000-0000000000d5'::uuid, 'Yeff, esta semana logré ir 3 veces', interval '2 hours')) x(pid, b, ago) join public.clients c2 on c2.profile_id = x.pid;

  -- ===== Agenda de Jeff =====
  for i in 1..10 loop
    d := today + i;
    if extract(isodow from d) in (6, 7) then continue; end if;
    insert into public.availability_slots (workspace_id, starts_at, kind, duration_min) values
      (ws, (d + time '07:00') at time zone 'America/Bogota', 'followup', 30), (ws, (d + time '12:30') at time zone 'America/Bogota', 'followup', 30),
      (ws, (d + time '18:00') at time zone 'America/Bogota', 'followup', 30), (ws, (d + time '19:00') at time zone 'America/Bogota', 'initial', 45);
  end loop;
  -- seguimientos pasados (cada 2 semanas) de Valentina
  for i in 1..5 loop
    d := vstart + i * 14 + 1;
    insert into public.availability_slots (workspace_id, starts_at, kind, duration_min) values (ws, (d + time '18:00') at time zone 'America/Bogota', 'followup', 30) returning id into s;
    insert into public.bookings (workspace_id, slot_id, client_id, booked_by, status) values (ws, s, va, 'client', 'completed');
  end loop;
  -- reservas próximas
  insert into public.bookings (workspace_id, slot_id, client_id, booked_by)
    select ws, (select id from public.availability_slots where starts_at > now() and kind = 'followup' order by starts_at offset x.o limit 1), c2.id, 'client'
    from (values ('00000000-0000-0000-0000-00000000000a'::uuid, 2), ('00000000-0000-0000-0000-0000000000d1'::uuid, 0), ('00000000-0000-0000-0000-0000000000d4'::uuid, 4), ('00000000-0000-0000-0000-0000000000d7'::uuid, 5)) x(pid, o)
    join public.clients c2 on c2.profile_id = x.pid;

  -- ===== Avisos y material =====
  insert into public.announcements (workspace_id, title, body, pinned, created_at) values
    (ws, 'Reto de diciembre', 'Todo diciembre: 8.000 pasos al día. Quien lo cumpla 25 de 31 días gana una sesión de técnica 1 a 1 conmigo.', true, now() - interval '1 day');
  insert into public.materials (workspace_id, kind, title, category, body, tier, is_featured, featured_period, featured_until, published, published_on) values
    (ws, 'article', 'Porciones sin pesar la comida', 'Nutrición', 'Usa tu mano como medida. Proteína: la palma de tu mano en cada comida. Carbohidratos: un puño. Verduras: dos puños. Grasas: un pulgar.' || E'\n\n' || 'No necesitas una báscula para avanzar: necesitas repetir lo mismo la mayoría de los días.', 'basic', true, 'week', today + 6, true, today - 2),
    (ws, 'article', 'Dormir para recuperar', 'Recuperación', 'El músculo crece cuando descansas. Apunta a 7 u 8 horas, a la misma hora todos los días, y deja la pantalla 30 minutos antes de dormir.', 'basic', false, 'week', null, true, today - 9),
    (ws, 'article', 'Técnica: la bisagra de cadera', 'Técnica', 'En el peso muerto rumano la cadera va hacia atrás, no hacia abajo. Rodillas suaves, espalda neutra y la barra pegada a las piernas.', 'full', false, 'week', null, true, today - 16);
end $$;

-- Semanas resumidas que Jeff envió a Valentina (la 12 todavía sin abrir)
do $$
declare jeff uuid := '00000000-0000-0000-0000-0000000000f0'; va uuid; vstart date := (now() at time zone 'America/Bogota')::date - 86; w int;
begin
  select id into va from public.clients where profile_id = '00000000-0000-0000-0000-00000000000a';
  perform pg_temp.as_user(jeff);
  for w in 9..12 loop
    perform public.send_week_summary(va, w, vstart + (w - 1) * 7, case w when 12 then 'Valentina, semana número 12 y la más fuerte hasta ahora: subiste carga en todo y no fallaste ningún entreno. Sigue durmiendo bien, eso se nota.' when 11 then 'Gran semana. Ojo con el agua el fin de semana.' else null end);
  end loop;
  reset role;
  update public.week_summaries set seen_at = now(), sent_at = (to_day + 1 + time '08:00') at time zone 'America/Bogota' where client_id = va and week_n < 12;
  update public.messages set read_at = now() where client_id = va and sender = 'coach' and id in (select message_id from public.week_summaries where client_id = va and week_n < 12);
end $$;

-- fechas de alta reales y reportes viejos (ya borrados) de los demás
update public.clients set created_at = coalesce(activated_at, created_at) - interval '2 days';
insert into public.daily_reports (workspace_id, client_id, report_date, comment, video_state, coach_seen_at, created_at)
  select w.workspace_id, w.client_id, w.log_date, 'Entreno completo.', 'deleted', w.completed_at + interval '3 hours', w.completed_at + interval '1 hour'
  from public.workout_logs w join public.clients c on c.id = w.client_id join public.profiles p on p.id = c.profile_id
  where p.full_name not in ('Valentina Ríos') and w.log_date < (now() at time zone 'America/Bogota')::date - 1 and pg_temp.rnd('rep' || w.id) < 0.7
  on conflict do nothing;
reset role;
select p.full_name, c.status, (select count(*) from public.workout_logs w where w.client_id = c.id) logs, (select count(*) from public.habit_logs h where h.client_id = c.id) hab
from public.clients c join public.profiles p on p.id = c.profile_id order by 1;
